CREATE TABLE IF NOT EXISTS "UserCredentials" (
  "userId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email VARCHAR(254) NOT NULL
    CHECK (email = lower(btrim(email)) AND length(email) > 0),
  "passwordHash" VARCHAR(100) NOT NULL CHECK (length("passwordHash") > 0),
  role VARCHAR(5) NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  CHECK ("userId" > 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS user_email_unique ON "UserCredentials" (email);

CREATE TABLE IF NOT EXISTS "UserProfile" (
  "profileId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "userId" INTEGER NOT NULL UNIQUE
    REFERENCES "UserCredentials" ("userId") ON DELETE CASCADE,
  "fullName" VARCHAR(100),
  phone VARCHAR(30)
);